const fs = process.getBuiltinModule("node:fs");

const mode = process.env.STUB_ESLINT_MODE ?? "errors";
const filePath = process.argv.at(-1);

if (process.env.STUB_ESLINT_LOG) {
  fs.writeFileSync(
    process.env.STUB_ESLINT_LOG,
    JSON.stringify({ argv: process.argv.slice(2), cwd: process.cwd() }),
  );
}

function output(messages, exitCode = 1) {
  const result = [
    {
      filePath,
      messages,
      errorCount: messages.filter((message) => message.severity === 2).length,
      warningCount: messages.filter((message) => message.severity === 1).length,
    },
  ];
  process.stdout.write(JSON.stringify(result));
  process.exitCode = exitCode;
}

switch (mode) {
  case "errors":
    output([
      {
        ruleId: "react-refresh/only-export-components",
        severity: 1,
        message: "Fast refresh only works when a file only exports components.",
        line: 1,
        column: 8,
      },
      {
        ruleId: "react-hooks/rules-of-hooks",
        severity: 2,
        message: "Hooks must be called at the top level.",
        line: 3,
        column: 5,
      },
    ]);
    break;
  case "warnings":
    output([
      {
        ruleId: "svelte/no-at-html-tags",
        severity: 1,
        message: "Avoid @html.",
        line: 8,
        column: 2,
      },
      {
        ruleId: "react-hooks/exhaustive-deps",
        severity: 1,
        message: "A dependency is missing.",
        line: 2,
        column: 1,
      },
    ]);
    break;
  case "ignored":
    output([
      {
        ruleId: null,
        severity: 1,
        message: "File ignored because of a matching ignore pattern.",
        line: 0,
        column: 0,
      },
    ], 0);
    break;
  case "fatal":
    output([
      {
        ruleId: null,
        fatal: true,
        severity: 2,
        message: "Parsing error.",
        line: 1,
        column: 1,
      },
    ]);
    break;
  case "crash":
    process.stderr.write("ESLint configuration failed.\n");
    process.exitCode = 2;
    break;
  case "garbage":
    process.stdout.write("not JSON");
    process.exitCode = 1;
    break;
  case "sleep":
    setTimeout(() => process.stdout.write("[]"), 5_000);
    break;
  case "many":
    output(
      Array.from({ length: 35 }, (_, index) => ({
        ruleId: "test/many",
        severity: 2,
        message: `Finding ${35 - index}`,
        line: 35 - index,
        column: 1,
      })),
    );
    break;
  case "multiline":
    output([
      {
        ruleId: "test/multiline",
        severity: 2,
        message: "First line\n  second line\r\nthird line",
        line: 4,
        column: 3,
      },
    ]);
    break;
  default:
    process.stdout.write("[]");
}
